'use strict';
const $=s=>document.querySelector(s), main=$('#main');
let config=JSON.parse(localStorage.getItem('quizConfig')||'null')||window.QUIZ_CONFIG, auth=JSON.parse(localStorage.getItem('quizAuth')||'null'), state=null, demo=false, demoItems=[], info={published:0,drafts:0,editor:false}, busy=false, catalog=[], clock=null, updatePoll=null, updateEpoch=0, importNotice='', importRunning=false, catalogPage=0, catalogTopic='', catalogSearch='', catalogSort='title';
const connected=()=>!!(config?.url&&config?.key);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sourceLink=u=>{try{const x=new URL(u);return x.protocol==='https:'?esc(x.href):'#'}catch{return '#'}};
async function api(path,body,method='POST',retry=true){if(!connected())throw Error('ჯერ დააკავშირეთ Supabase');if(auth?.expires_at<Date.now()/1000+30&&retry){const r=await api('/auth/v1/token?grant_type=refresh_token',{refresh_token:auth.refresh_token},'POST',false);saveAuth(r)}const r=await fetch(config.url+path,{method,headers:{apikey:config.key,...(auth?.access_token?{Authorization:'Bearer '+auth.access_token}:config.key.startsWith('eyJ')?{Authorization:'Bearer '+config.key}:{}),'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json().catch(()=>null);if(!r.ok)throw Error(data?.message||data?.msg||data?.error_description||'მოთხოვნა ვერ შესრულდა');return data}
const rpc=(name,body={})=>api('/rest/v1/rpc/'+name,body);
function saveAuth(a){auth=a?.access_token?{...a,expires_at:a.expires_at||Date.now()/1000+a.expires_in}:null;if(auth)localStorage.setItem('quizAuth',JSON.stringify(auth));else localStorage.removeItem('quizAuth');$('#account').textContent=auth?'გასვლა':'შესვლა'}
async function refreshInfo(){if(connected())try{info=await rpc('game_info');catalog=await rpc('quiz_catalog')}catch(e){info.error=e.message}$('#adminNav').hidden=!info.editor}

function filteredCatalog(){const rows=catalog.filter(q=>(!catalogTopic||q.theme===catalogTopic)&&(!catalogSearch||(`${q.title} ${q.theme}`).toLocaleLowerCase().includes(catalogSearch.toLocaleLowerCase())));return rows.sort((a,b)=>catalogSort==='shortest'?a.question_count-b.question_count:catalogSort==='longest'?b.question_count-a.question_count:a.title.localeCompare(b.title,'ka'))}
function catalogControls(){return `<div class="catalog-search-wrap"><span aria-hidden="true">⌕</span><label class="sr-only" for="catalogSearch">ქუიზის ძებნა</label><input id="catalogSearch" value="${esc(catalogSearch)}" type="search" placeholder="მოძებნე ქუიზი ან თემა" autocomplete="off"></div><label class="catalog-sort-label">დალაგება<select id="catalogSort"><option value="title" ${catalogSort==='title'?'selected':''}>სათაურით</option><option value="shortest" ${catalogSort==='shortest'?'selected':''}>მოკლე ქუიზები</option><option value="longest" ${catalogSort==='longest'?'selected':''}>გრძელი ქუიზები</option></select></label>`}
function catalogMarkup(){const rows=filteredCatalog();catalogPage=Math.min(catalogPage,Math.max(0,Math.ceil(rows.length/24)-1));return rows.slice(catalogPage*24,catalogPage*24+24).map((q,i)=>`<article class="card quiz-card" style="--card-index:${i%8}"><span class="tag">${esc(q.theme)}</span><h2>${esc(q.title)}</h2><div class="quiz-meta"><span><b aria-hidden="true">▦</b>${q.question_count} კითხვა</span><span><b aria-hidden="true">◷</b>დაახლ. ${Math.max(1,Math.round(q.question_count*40/60))} წთ</span></div><button class="primary" data-quiz="${esc(q.id)}">ქუიზის დაწყება <span aria-hidden="true">↗</span></button></article>`).join('')||'<div class="empty-state"><h2>ამ ძებნით ქუიზი ვერ მოიძებნა</h2><p>შეცვალე თემა ან საძიებო სიტყვა.</p></div>'}
function bindCatalog(){if(!catalog.length)return;const render=()=>{$('#catalogGrid').innerHTML=catalogMarkup();const n=filteredCatalog().length,pages=Math.ceil(n/24);$('#catalogResultCount').textContent=`${n} ქუიზი ნაჩვენებია`;$('#catalogPages').innerHTML=`<p>${n} ქუიზი · გვერდი ${pages?catalogPage+1:0}/${pages}</p><button id="catalogPrev" ${catalogPage===0?'disabled':''}>წინა</button><button id="catalogNext" ${catalogPage+1>=pages?'disabled':''}>შემდეგი</button>`;$('#catalogPrev').onclick=()=>{catalogPage--;render()};$('#catalogNext').onclick=()=>{catalogPage++;render()};document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>start('quiz',b.dataset.quiz));};$('#catalogSort').onchange=e=>{catalogSort=e.target.value;catalogPage=0;render()};$('#catalogSearch').oninput=e=>{catalogSearch=e.target.value;catalogPage=0;render()};render()}
function setActiveView(view){document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('nav-active',active);b.setAttribute('aria-current',active?'page':'false')})}
function categoryTiles(){const themes=[...new Set(catalog.map(q=>q.theme))];if(!themes.length)return '<div class="empty-state"><p>ქუიზების სია იტვირთება ან ჯერ არ გამოქვეყნებულა.</p><button class="primary" data-open-quizzes>ქუიზების ნახვა</button></div>';return themes.map((theme,i)=>{const count=catalog.filter(q=>q.theme===theme).length;return `<button class="category-tile tone-${i%5}" data-theme="${esc(theme)}"><span class="category-number">0${i+1}</span><span class="category-name">${esc(theme)}</span><span class="category-count">${count} ქუიზი</span><span class="category-arrow" aria-hidden="true">↗</span></button>`}).join('')}
function home(){setActiveView('home');stopUpdates();clearInterval(clock);state=null;const themes=[...new Set(catalog.map(q=>q.theme))];main.innerHTML=`<section class="home-hero"><div class="home-copy"><span class="eyebrow"><span class="live-dot"></span> ცოდნა და ლოგიკა — თამაშის ფორმით</span><h1>ჯანდაცვა,<br><em>სხვა კუთხით.</em></h1><p class="intro">მოკლე, თემატური ქუიზები საზოგადოებრივ ჯანდაცვასა და ჯანდაცვის მენეჯმენტზე. ითამაშე, შეამოწმე შენი მსჯელობა და დაიკავე ადგილი რეიტინგში.</p><div class="home-actions"><button class="primary" id="exploreQuizzes">ქუიზების არჩევა <span aria-hidden="true">↗</span></button><button class="secondary-action" id="dailyShortcut">დღის ქუიზი <span aria-hidden="true">→</span></button></div><div class="stats home-stats"><span><strong>${catalog.length}</strong>გამოქვეყნებული ქუიზი</span><span><strong>${themes.length}</strong>თემატური მიმართულება</span><span><strong>15–30</strong>კითხვა ერთ თამაშში</span></div></div><div class="home-art" aria-hidden="true"><div class="art-ring ring-a"></div><div class="art-ring ring-b"></div><div class="art-card"><span class="art-label">დღის გამოწვევა</span><span class="art-icon">✳</span><strong>იფიქრე.<br>უპასუხე.<br>გაიმარჯვე.</strong><span class="art-foot">საზოგადოებრივი ჯანდაცვა</span></div><span class="art-float float-one">15 კითხვა <b>→</b></span><span class="art-float float-two">ცოდნა + ლოგიკა</span></div></section>${!connected()?'<div class="notice">რეგისტრაცია და ონლაინ რეიტინგი Supabase-თან დაკავშირების შემდეგ მუშაობს.</div>':''}<section class="daily-feature"><div class="daily-icon" aria-hidden="true">☼</div><div class="daily-text"><span class="eyebrow">დღეს რას ვითამაშებთ?</span><h2>დღის ქუიზი</h2><p>ყოველდღე ახალი, 15-კითხვიანი გამოწვევა. ჯანმრთელობის მნიშვნელოვან თარიღებზე — შესაბამისი თემით.</p></div><button class="primary" id="daily" ${connected()?'':'disabled'}>დაწყება <span aria-hidden="true">↗</span></button></section><section class="home-categories"><div class="section-heading"><div><span class="eyebrow">აირჩიე შენი მიმართულება</span><h2>თემები, რომლებსაც ვითამაშებთ</h2></div><button class="text-action" data-open-quizzes>ყველა ქუიზი <span aria-hidden="true">↗</span></button></div><div class="category-grid">${categoryTiles()}</div></section><section class="how-strip"><div><span>01</span><b>აირჩიე თემა</b><small>ეპიდემიოლოგია, პრევენცია და სხვა</small></div><div><span>02</span><b>ითამაშე შენს ტემპში</b><small>ცოდნა და ლოგიკა ერთად მუშაობს</small></div><div><span>03</span><b>შეადარე შედეგი</b><small>რეიტინგში დაინახავ შენს ადგილს</small></div></section>${info.error?'<p class="error">'+esc(info.error)+'</p>':''}`;$('#daily').onclick=()=>start('daily');$('#dailyShortcut').onclick=()=>start('daily');$('#exploreQuizzes').onclick=()=>quizzes();document.querySelectorAll('[data-open-quizzes]').forEach(b=>b.onclick=()=>quizzes());document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>quizzes(b.dataset.theme))}
function quizzes(theme=''){setActiveView('quizzes');stopUpdates();clearInterval(clock);state=null;catalogTopic=theme;main.innerHTML=`<section class="catalog-page"><div class="catalog-heading"><div><span class="eyebrow">თემატური თამაშების ბიბლიოთეკა</span><h1>აირჩიე ქუიზი.</h1><p>მოძებნე სათაურით ან გაფილტრე თემის მიხედვით. აირჩიე შენთვის მოსახერხებელი სიგრძე.</p></div><div class="catalog-total"><strong>${catalog.length}</strong><span>ქუიზი ხელმისაწვდომია</span></div></div>${catalog.length?`<div class="catalog-toolbar">${catalogControls()}</div><div class="catalog-topic-list">${['ყველა თემა',...new Set(catalog.map(q=>q.theme))].map(t=>`<button class="topic-filter ${(!catalogTopic&&t==='ყველა თემა')||catalogTopic===t?'selected':''}" data-topic="${t==='ყველა თემა'?'':esc(t)}">${esc(t)}</button>`).join('')}</div><div id="catalogResultCount" class="catalog-result-count" aria-live="polite"></div><section id="catalogGrid" class="grid quiz-grid"></section><div id="catalogPages" class="catalog-pagination"></div>`:`<div class="empty-state"><h2>ქუიზები ჯერ არ არის გამოქვეყნებული</h2><p>როგორც კი თემატური პაკეტები გამოჩნდება, აქედან აირჩევ თამაშს.</p><button class="secondary-action" id="backHome">მთავარ გვერდზე</button></div>`}</section>`;if(catalog.length){bindCatalog();document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{catalogTopic=b.dataset.topic;catalogPage=0;quizzes(catalogTopic)});}if($('#backHome'))$('#backHome').onclick=home}

async function start(mode,quizId=null){if(busy)return;if(mode!=='demo'&&connected()&&!auth){$('#auth').showModal();return}busy=true;try{demo=mode==='demo';if(demo){const bank=await(await fetch('demo-questions.json')).json();demoItems=bank.map(x=>({...x,r:Math.random()})).sort((a,b)=>a.r-b.r).slice(0,15);state={position:0,total:demoItems.length,score:0,mode:'quiz',title:'სატესტო ქუიზი',expires_at:Date.now()/1000+600,finished:false,question:demoItems[0]}}else state=await rpc('start_game',{p_mode:mode,p_quiz:quizId});renderQuiz()}catch(e){alert(e.message)}finally{busy=false}}
function renderQuiz(){clearInterval(clock);if(state.finished){main.innerHTML=`<section class="quiz card empty"><span class="tag">${demo?'დემო დასრულებულია':'ქუიზი დასრულებულია'}</span><h2>შენი შედეგი მზადაა.</h2><div class="score">${state.score}</div><p>${state.total*100} შესაძლო ქულიდან</p><p>${demo?'სატესტო მონახაზები; წყარო მითითებულია, სარედაქციო დამტკიცება ჯერ საჭიროა.':state.position===0?'პასუხი არ დაგიფიქსირებია — ეს ცდა რეიტინგში არ ჩაითვლება. შეგიძლია ქუიზი თავიდან დაიწყო.':state.mode==='daily'?'შედეგი დღის საერთო რეიტინგში შენახულია.':'შედეგი ქუიზის რეიტინგში შენახულია.'}</p><button class="primary" id="again">მთავარ გვერდზე</button>${state.position>0?'<button id="reviewResult">პასუხები და წყაროები</button>':''}</section>`;$('#again').onclick=home;if($('#reviewResult'))$('#reviewResult').onclick=results;return}const q=state.question;main.innerHTML=`<section class="quiz"><div class="row"><span class="tag">${demo?'სატესტო მონახაზი':state.mode==='daily'?'დღის ქუიზი':esc(state.title)}</span><span>${state.position+1} / ${state.total}</span><span style="margin-left:auto">${state.score} ქულა · <b id="timer"></b></span></div><div class="progress"><div style="width:${state.position/state.total*100}%"></div></div><article class="card"><span class="eyebrow">${esc(q.topic)}</span><h2>${esc(q.prompt)}</h2><div class="options">${q.options.map((o,i)=>`<button class="option" data-choice="${i}"><b>${'აბგდ'[i]}</b><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback" aria-live="polite"></div></article></section>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.choice)));const tick=()=>{const left=Math.max(0,Math.ceil(state.expires_at-Date.now()/1000));if($('#timer'))$('#timer').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(left===0){clearInterval(clock);if(demo){state.finished=true;renderQuiz()}else if(!busy){answer(0)}}};tick();clock=setInterval(tick,1000)}
async function answer(choice){if(busy)return;busy=true;document.querySelectorAll('[data-choice]').forEach(b=>b.disabled=true);try{let r;if(demo){const q=demoItems[state.position],correct=choice===q.answer_index;const next={...state,score:state.score+(correct?100:0),position:state.position+1};next.finished=next.position===next.total;next.question=demoItems[next.position];r={state:next}}else r=await rpc('answer_game',{p_session:state.session_id,p_position:state.position,p_choice:choice});state=r.state;renderQuiz()}catch(e){$('#feedback').innerHTML='<p class="error">'+esc(e.message)+'</p>';document.querySelectorAll('[data-choice]').forEach(b=>b.disabled=false)}finally{busy=false}}
async function results(){try{const rows=demo?demoItems:await rpc('quiz_results',{p_session:state.session_id});main.innerHTML='<h1>პასუხები და წყაროები</h1>'+rows.map(q=>`<article class="card review"><h2>${esc(q.prompt)}</h2><strong>${esc(q.options[q.answer_index])}</strong><p>${esc(q.explanation)}</p><a href="${sourceLink(q.source_url)}" target="_blank" rel="noopener noreferrer">${esc(q.source_title)} ↗</a><p>${esc(q.source_locator)}</p></article>`).join('')+'<button id="backResult">შედეგზე დაბრუნება</button>';$('#backResult').onclick=renderQuiz}catch(e){alert(e.message)}}
async function leaders(mode='quiz',quizId=null,period='week'){setActiveView('leaders');stopUpdates();clearInterval(clock);main.innerHTML=`<h1>რეიტინგი</h1><p>${mode==='daily'?'დღის ქუიზი: არჩეულ პერიოდში დასრულებული დღეების საშუალო პროცენტი.':'ქუიზები: თითო ქუიზზე პირველი ცდა, საშუალო პროცენტი. განსხვავებული სიგრძის ქუიზები პროცენტით ფასდება.'}</p><div class="row"><button id="quizLeaders" class="${mode==='quiz'?'primary':''}">ქუიზები</button><button id="dailyLeaders" class="${mode==='daily'?'primary':''}">დღის ქუიზი</button>${mode==='daily'?[['day','დღეს'],['week','კვირა'],['month','თვე']].map(([v,t])=>`<button data-period="${v}" class="${v===period?'primary':''}">${t}</button>`).join(''):''}</div>${mode==='quiz'?'<label>ქუიზი<select id="quizFilter"><option value="">ყველა ქუიზი</option>'+catalog.map(q=>`<option value="${esc(q.id)}" ${q.id===quizId?'selected':''}>${esc(q.title)}</option>`).join('')+'</select></label>':''}<section id="board" class="card" style="margin-top:22px">იტვირთება…</section>`;$('#quizLeaders').onclick=()=>leaders('quiz');$('#dailyLeaders').onclick=()=>leaders('daily');if($('#quizFilter'))$('#quizFilter').onchange=e=>leaders('quiz',e.target.value||null);document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>leaders(mode,quizId,b.dataset.period));try{const rows=connected()?await rpc('leaderboard',{p_mode:mode,p_quiz:quizId,p_period:period}):[];$('#board').innerHTML=rows.length?rows.map((r,i)=>`<div class="leader"><b>${i+1}</b><span>${esc(r.nickname)}<small style="display:block;color:var(--muted)">${r.rounds} დასრულებული ქუიზი</small></span><strong>${r.points}%</strong></div>`).join(''):`<div class="empty"><h2>${connected()?'პირველი ადგილი გელოდება.':'ონლაინ რეიტინგი ჯერ არ არის დაკავშირებული.'}</h2></div>`}catch(e){$('#board').textContent=e.message}}

function stopUpdates(){clearTimeout(updatePoll);updatePoll=null;updateEpoch++}
function updatePanel(){return `<section class="card review" id="updatePanel"><h2>სამეცნიერო წყაროების შემოწმება</h2><p>განახლება ეძებს ახალ სამეცნიერო წყაროებს. წყაროს აღმოჩენა ჯერ კითხვის შექმნას არ ნიშნავს. შექმნილი კითხვები ინახება მხოლოდ მონახაზებად და გამოქვეყნებამდე შემოწმებას საჭიროებს.</p><button class="primary" id="runUpdates" disabled>ახალი წყაროების მოძიება</button><p id="updateMessage" aria-live="polite">განახლების პარამეტრები იტვირთება…</p><div id="updateStatus"></div><div id="updateFlags"></div><div id="updateSources"></div></section>`}
async function updaterRequest(path,method='GET',body){if(!auth?.access_token)throw Error('განახლებისთვის შედით ადმინისტრატორის ანგარიშით');await rpc('game_info');const r=await fetch(path,{method,headers:{Authorization:'Bearer '+auth.access_token,'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await r.json().catch(()=>null);if(!r.ok)throw Error(data?.error||data?.message||'განახლების სერვისთან დაკავშირება ვერ მოხერხდა');return data}
const updateStatusLabel=s=>({queued:'რიგშია',running:'მიმდინარეობს',completed:'დასრულებულია',complete:'დასრულებულია',succeeded:'დასრულებულია',partial:'ნაწილობრივ დასრულებულია',drafted:'მონახაზები შექმნილია',draft_failed:'მონახაზი ვერ შეიქმნა',failed:'შეცდომა',draft:'მონახაზი',discovered:'აღმოჩენილი წყარო',new:'ახალი წყარო',processed:'დამუშავებულია'}[s]||s||'უცნობი სტატუსი');
function updateSummary(summary){if(!summary)return '';if(typeof summary!=='object')return esc(summary);return Object.entries(summary).map(([k,v])=>`${esc(({checked:'შემოწმებული წყაროები',changed:'შეცვლილი წყაროები',unreachable:'მიუწვდომელი წყაროები',discovered:'მოძიებული ჩანაწერები',sources_found:'აღმოჩენილი წყაროები',sources_added:'დამატებული წყაროები',new_sources:'ახალი წყაროები',drafts_created:'შექმნილი მონახაზები',questions_created:'შექმნილი მონახაზები',errors:'შეცდომები',fetched:'შემოწმებული წყაროები',added:'დამატებული წყაროები',skipped:'გამოტოვებული წყაროები'}[k]||k))}: ${esc(typeof v==='object'?JSON.stringify(v):v)}`).join(' · ')}
function updateDate(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?esc(v):esc(d.toLocaleString('ka-GE'))}
function renderUpdates(data,epoch){if(epoch!==updateEpoch||!$('#updatePanel'))return;const button=$('#runUpdates');button.disabled=!data.configured;$('#updateMessage').textContent=data.configured?'წყაროების აღმოჩენის სერვისი დაკავშირებულია. აღმოჩენილი წყაროები ავტომატურად არ ქვეყნდება.':'განახლების სერვისი ჯერ არ არის გამართული. საჭიროა სერვერის კონფიგურაცია.';$('#updateStatus').innerHTML=`<p>შემდეგი დაგეგმილი შემოწმება: ${updateDate(data.next_due)}</p><p>${data.ai_enabled?'წყაროების ავტომატური აღმოჩენა კითხვების დამტკიცებას არ ნიშნავს. თამაშისთვის გარე API საჭირო არ არის.':'ეს განახლება მხოლოდ წყაროებს აღმოაჩენს. თამაშს ფასიანი ხელოვნური ინტელექტი ან გარე API-ს ინტეგრაცია არ სჭირდება; წყაროების სერვერი არჩევითია.'}</p>`+(data.jobs||[]).slice(0,8).map(j=>`<div class="review"><strong>${esc(updateStatusLabel(j.status))}</strong><p>დაწყება: ${updateDate(j.started_at)} · დასრულება: ${updateDate(j.finished_at)}</p><p>${updateSummary(j.summary)}</p></div>`).join('');$('#updateFlags').innerHTML=(data.flags||[]).map(f=>`<article class="notice"><strong>${esc(f.prompt)}</strong><p>${esc(f.reason)}</p><button data-clear-flag="${esc(f.id)}">გადავამოწმე — პასუხი კვლავ სწორია</button></article>`).join('');document.querySelectorAll('[data-clear-flag]').forEach(b=>b.onclick=async()=>{try{await rpc('clear_question_flag',{p_id:b.dataset.clearFlag});loadUpdates(epoch)}catch(e){alert(e.message)}});$('#updateSources').innerHTML=(data.sources||[]).map(source=>`<article class="card review"><span class="tag">${esc(source.topic||'ახალი წყარო')}</span><h3>${esc(source.title)}</h3><p>${esc(updateStatusLabel(source.status))} · გამოქვეყნების თარიღი: ${updateDate(source.published_at)}</p><a href="${sourceLink(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.url)}</a><p><button data-source-draft="${esc(source.id)}" ${data.ai_enabled&&source.status!=='drafted'?'':'disabled'}>წყაროდან კითხვების მონახაზების შექმნა</button></p></article>`).join('')||'<p>აღმოჩენილი წყაროები ჯერ არ არის.</p>';document.querySelectorAll('[data-source-draft]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const result=await updaterRequest('/api/drafts','POST',{source_id:b.dataset.sourceDraft});if(epoch!==updateEpoch)return;await loadUpdates(epoch);if($('#updateMessage'))$('#updateMessage').textContent='მოთხოვნა შესრულებულია. შედეგი ინახება მხოლოდ მონახაზად: '+(typeof result.summary==='string'?result.summary:JSON.stringify(result.summary||result));}catch(e){if(epoch===updateEpoch&&$('#updateMessage'))$('#updateMessage').textContent=e.message;}finally{if(epoch===updateEpoch&&b.isConnected)b.disabled=false}})}
async function loadUpdates(epoch){const data=await updaterRequest('/api/updates');renderUpdates(data,epoch);return data}
function bindUpdates(){const epoch=updateEpoch;loadUpdates(epoch).catch(e=>{if(epoch===updateEpoch&&$('#updateMessage')){$('#runUpdates').disabled=true;$('#updateMessage').textContent='წყაროების სერვისი ჯერ არ არის დაკავშირებული. კითხვებისა და ქუიზების მართვა მუშაობს დამოუკიდებლად. '+e.message;}});$('#runUpdates').onclick=async()=>{stopUpdates();const current=updateEpoch;const button=$('#runUpdates');button.disabled=true;$('#updateMessage').textContent='წყაროების შემოწმების დაწყება…';try{const result=await updaterRequest('/api/updates','POST');if(current!==updateEpoch)return;let attempts=0;const poll=async()=>{if(current!==updateEpoch)return;attempts++;try{const data=await loadUpdates(current);if(current!==updateEpoch)return;const job=(data.jobs||[]).find(j=>j.id===result.job_id);if(job&&['completed','complete','succeeded','partial','failed'].includes(job.status))return;if(attempts<20)updatePoll=setTimeout(poll,3000);else if($('#updateMessage'))$('#updateMessage').textContent='შემოწმება შესაძლოა ჯერ მიმდინარეობდეს. სტატუსის სანახავად ხელახლა გახსენით მართვის გვერდი.';}catch(e){if(current===updateEpoch&&$('#updateMessage'))$('#updateMessage').textContent=e.message;}};await poll();}catch(e){if(current===updateEpoch&&$('#updateMessage'))$('#updateMessage').textContent=e.message;}finally{if(current===updateEpoch&&button.isConnected)button.disabled=false}}}

async function bulkImport(kind,file){if(importRunning)return;const progress=$('#importProgress');let committed=0,inserted=0;try{if(!auth||!info.editor)throw Error('ატვირთვა მხოლოდ შესულ რედაქტორს შეუძლია');if(!file)return;const items=JSON.parse(await file.text());if(!Array.isArray(items))throw Error('ფაილი უნდა შეიცავდეს JSON მასივს');if(items.length>10000)throw Error('ერთ ფაილში 10,000-ზე მეტი ჩანაწერი არ დაიშვება; გაყავით ფაილი ნაწილებად');if(!items.length)throw Error('ფაილი ცარიელია');importRunning=true;$('#import').disabled=true;$('#importQuiz').disabled=true;const size=kind==='questions'?500:50,total=Math.ceil(items.length/size);for(let offset=0;offset<items.length;offset+=size){if(progress.isConnected)progress.textContent=`იტვირთება ნაწილი ${committed+1}/${total} · დასრულებულია ${offset}/${items.length} ჩანაწერი…`;const result=await rpc(kind==='questions'?'import_questions':'import_quizzes',{p_items:items.slice(offset,offset+size)});committed++;const count=typeof result==='number'?result:result?.inserted??result?.count??result?.added;inserted+=Number(count)||0;}const activated=await rpc('publish_imported_bank',{p_bank:'main'});importNotice=`ატვირთვა დასრულებულია: ${committed} ნაწილი, ${items.length} დამუშავებული ჩანაწერი, სერვერის მიხედვით ${inserted} დამატებული. ეს არის კითხვის ვარიანტების რაოდენობა — დამოუკიდებელი კონცეფციების რაოდენობას ოჯახები აჩვენებს. ძირითადი ბაზა თამაშისთვის ჩართულია; სრულად შევსებული ქუიზები ავტომატურად ქვეყნდება. სარეზერვო კითხვები ინახება მონახაზად.`;await refreshInfo();await admin('upload');}catch(e){importNotice=`${e.message} · წარმატებით შენახულია ${committed} ნაწილი. ატვირთვის გამეორება უსაფრთხოა იგივე UUID-ებით: უკვე შენახული ჩანაწერები დუბლიკატებად არ ემატება.`;const target=$('#importProgress');if(target)target.textContent=importNotice;}finally{importRunning=false;if($('#import'))$('#import').disabled=false;if($('#importQuiz'))$('#importQuiz').disabled=false}}
async function loadFamilies(){const target=$('#familyDrafts');target.innerHTML='<h2>ბაზის ჩართვა</h2><p>ძირითადი კითხვები და სრულად შევსებული ქუიზები ატვირთვის შემდეგ ავტომატურად ქვეყნდება. სარეზერვო ბაზა ინახება შემდეგი განახლებისთვის.</p><button id="activateBank" class="primary">ატვირთული ძირითადი ბაზის ჩართვა</button><p id="activateMessage" aria-live="polite"></p>';$('#activateBank').onclick=async()=>{const button=$('#activateBank');button.disabled=true;try{const result=await rpc('publish_imported_bank',{p_bank:'main'});$('#activateMessage').textContent=`ჩართულია ${result.questions} კითხვა და ${result.quizzes} ქუიზი.`;await refreshInfo();}catch(e){$('#activateMessage').textContent=e.message;}finally{button.disabled=false}}}

let editorPage=0,editorSearch='',editorStatus='',editorTopic='',editorEpoch=0;
function quizEditorPanel(){return '<section class="card"><h2>ქუიზების რედაქტირება</h2><form id="editorSearchForm" class="row"><label>ძებნა<input id="editorSearch" placeholder="ქუიზის სახელი ან თემა" value="'+esc(editorSearch)+'"></label><label>კატეგორია<select id="editorTopic"><option value="">ყველა კატეგორია</option></select></label><label>სტატუსი<select id="editorStatus"><option value="">ყველა</option><option value="published">გამოქვეყნებული</option><option value="draft">მონახაზი / დამალული</option></select></label><button type="submit">ძებნა</button></form><p id="editorSummary" aria-live="polite"></p><div class="row"><button id="selectQuizPage">ამ გვერდის მონიშვნა</button><button id="bulkQuizPublish">მონიშნულების გამოქვეყნება</button><button id="bulkQuizHide">მონიშნულების დამალვა</button></div><p id="bulkQuizMessage" aria-live="polite"></p><div id="quizEditorRows"></div><div id="editorPages" class="row"></div></section>'}
function bindQuizEditor(){ $('#selectQuizPage').onclick=()=>document.querySelectorAll('[data-bulk-quiz]').forEach(c=>c.checked=true);for(const [id,status] of [['bulkQuizPublish','published'],['bulkQuizHide','draft']])$('#'+id).onclick=async()=>{const ids=[...document.querySelectorAll('[data-bulk-quiz]')].filter(c=>c.checked).map(c=>c.dataset.bulkQuiz);if(!ids.length){$('#bulkQuizMessage').textContent='მონიშნეთ ქუიზები.';return}const b=$('#'+id);b.disabled=true;try{const n=await rpc('admin_quiz_status_many',{p_ids:ids,p_status:status});$('#bulkQuizMessage').textContent=`შეიცვალა ${n} ქუიზი.`;await refreshInfo();loadQuizEditor()}catch(e){$('#bulkQuizMessage').textContent=e.message}finally{b.disabled=false}};$('#editorStatus').value=editorStatus;$('#editorSearchForm').onsubmit=e=>{e.preventDefault();editorSearch=$('#editorSearch').value.trim();editorStatus=$('#editorStatus').value;editorTopic=$('#editorTopic').value;editorPage=0;loadQuizEditor()};$('#editorTopic').onchange=()=>{editorTopic=$('#editorTopic').value;editorSearch=$('#editorSearch').value.trim();editorStatus=$('#editorStatus').value;editorPage=0;loadQuizEditor()};loadQuizEditor() }
async function loadQuizEditor(){const epoch=++editorEpoch,target=$('#quizEditorRows');$('#editorSummary').textContent='იტვირთება…';try{const data=await rpc('admin_quiz_list_by_theme',{p_search:editorSearch,p_status:editorStatus,p_page:editorPage,p_theme:editorTopic});if(epoch!==editorEpoch||!target.isConnected)return;if($('#editorTopic')){$('#editorTopic').innerHTML='<option value="">ყველა კატეგორია</option>'+(data.themes||[]).map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('#editorTopic').value=editorTopic;}const rows=data.items||[];if(!rows.length&&editorPage>0){editorPage--;return loadQuizEditor()}$('#editorSummary').textContent=`${data.total} ქუიზი · გვერდი ${data.total?editorPage+1:0}/${Math.ceil(data.total/20)}`;target.innerHTML=rows.map((q,i)=>`<form class="review card" id="editQuiz${i}"><label><input type="checkbox" data-bulk-quiz="${esc(q.id)}"> მონიშვნა</label><span class="tag">${q.status==='published'?'გამოქვეყნებული':q.admin_hidden?'დამალული':'მონახაზი'} · ${q.question_count} კითხვა</span><label>ქუიზის სახელი<input id="editTitle${i}" value="${esc(q.title)}" required minlength="2" maxlength="160"></label><label>თემა<input id="editTheme${i}" value="${esc(q.theme)}" required minlength="2" maxlength="100"></label><div class="row"><button type="submit" class="primary" id="editSave${i}">ცვლილებების შენახვა</button><button type="button" id="editToggle${i}">${q.status==='published'?'დამალვა':'გამოქვეყნება'}</button></div><p id="editMessage${i}" aria-live="polite"></p></form>`).join('')||'<p>ქუიზი ვერ მოიძებნა.</p>';rows.forEach((q,i)=>{const form=$('#editQuiz'+i);const save=async(status)=>{if(!form.reportValidity())return;const message=$('#editMessage'+i),saveButton=$('#editSave'+i),toggle=$('#editToggle'+i);saveButton.disabled=toggle.disabled=true;try{await rpc('admin_save_quiz',{p_id:q.id,p_title:$('#editTitle'+i).value.trim(),p_theme:$('#editTheme'+i).value.trim(),p_status:status});message.textContent='შენახულია.';await refreshInfo();if(target.isConnected)await loadQuizEditor()}catch(e){message.textContent=e.message;}finally{if(saveButton.isConnected)saveButton.disabled=toggle.disabled=false}};form.onsubmit=e=>{e.preventDefault();save(q.status)};$('#editToggle'+i).onclick=()=>save(q.status==='published'?'draft':'published')});$('#editorPages').innerHTML=`<button id="editorPrev" ${editorPage===0?'disabled':''}>წინა</button><button id="editorNext" ${(editorPage+1)*20>=data.total?'disabled':''}>შემდეგი</button>`;$('#editorPrev').onclick=()=>{editorPage--;loadQuizEditor()};$('#editorNext').onclick=()=>{editorPage++;loadQuizEditor()};}catch(e){if(epoch===editorEpoch&&target.isConnected)$('#editorSummary').textContent=e.message}}

let questionPage=0,questionSearch='',questionStatus='',questionTopic='',questionEpoch=0,adminTopics=[];
function questionPanel(){return `<section class="card"><h2>კითხვების რედაქტირება</h2><form id="questionSearchForm" class="row"><label>ძებნა<input id="questionSearch" value="${esc(questionSearch)}" placeholder="კითხვის ტექსტი"></label><label>სტატუსი<select id="questionStatus"><option value="">ყველა</option><option value="published">გამოქვეყნებული</option><option value="draft">მონახაზი</option><option value="retired">არქივი</option></select></label><label>თემა<select id="questionTopic"><option value="">ყველა თემა</option>${adminTopics.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label><button>ძებნა</button><button type="button" id="newQuestion">ახალი კითხვა</button></form><p id="questionSummary" aria-live="polite"></p><div id="questionRows"></div><div class="row" id="questionPages"></div></section>`}
function questionForm(q,i){return `<details class="card review" ${q.id?'':'open'}><summary>${esc(q.prompt||'ახალი კითხვა')} <span class="tag">${({published:'გამოქვეყნებული',draft:'მონახაზი',retired:'არქივი'})[q.status]||'მონახაზი'}</span></summary><form id="questionForm${i}"><label>კითხვა<textarea id="qPrompt${i}" required minlength="10" maxlength="2000">${esc(q.prompt)}</textarea></label>${(q.options||['','','','']).map((v,k)=>`<label>პასუხი ${k+1}<input id="qOption${i}_${k}" required maxlength="600" value="${esc(v)}"></label>`).join('')}<div class="row"><label>სწორი პასუხი<select id="qAnswer${i}">${[0,1,2,3].map(k=>`<option value="${k}" ${q.answer_index===k?'selected':''}>პასუხი ${k+1}</option>`).join('')}</select></label><label>სირთულე<select id="qDifficulty${i}">${[1,2,3].map(k=>`<option value="${k}" ${q.difficulty===k?'selected':''}>${['საბაზისო','საშუალო','რთული'][k-1]}</option>`).join('')}</select></label><label>სტატუსი<select id="qStatus${i}">${[['published','გამოქვეყნებული'],['draft','მონახაზი'],['retired','არქივი']].map(([v,t])=>`<option value="${v}" ${q.status===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label>თემა<input id="qTopic${i}" required maxlength="100" value="${esc(q.topic)}"></label><label>პასუხის განმარტება<textarea id="qExplanation${i}" required minlength="20" maxlength="6000">${esc(q.explanation)}</textarea></label><label>წყაროს ბმული<input id="qUrl${i}" required type="url" value="${esc(q.source_url)}"></label><label>წყაროს სათაური<input id="qSource${i}" required value="${esc(q.source_title)}"></label><label>წყაროს შესაბამისი ნაწილი<input id="qLocator${i}" required minlength="6" value="${esc(q.source_locator)}"></label><p>კითხვის მონახაზად ან არქივში გადატანა მასზე დამოკიდებულ ქუიზებსაც დამალავს. უკვე დაწყებული თამაშები ინახავს საწყის კითხვებს.</p><button class="primary" id="qSave${i}">შენახვა</button><p id="qMessage${i}" aria-live="polite"></p></form></details>`}
function bindQuestionForms(rows){rows.forEach((q,i)=>{$('#questionForm'+i).onsubmit=async e=>{e.preventDefault();const form=$('#questionForm'+i);if(!form.reportValidity())return;const b=$('#qSave'+i),msg=$('#qMessage'+i);b.disabled=true;try{const savedId=await rpc('admin_save_question',{p_id:q.id||null,p_item:{prompt:$('#qPrompt'+i).value,options:[0,1,2,3].map(k=>$('#qOption'+i+'_'+k).value.trim()),answer_index:Number($('#qAnswer'+i).value),difficulty:Number($('#qDifficulty'+i).value),status:$('#qStatus'+i).value,topic:$('#qTopic'+i).value,explanation:$('#qExplanation'+i).value,source_url:$('#qUrl'+i).value.trim(),source_title:$('#qSource'+i).value,source_locator:$('#qLocator'+i).value,kind:q.kind||'knowledge'}});q.id=savedId;msg.textContent='შენახულია. განახლებული სიის სანახავად დააჭირეთ ძებნას.';await refreshInfo();}catch(err){msg.textContent=err.message}finally{b.disabled=false}}})}
async function loadQuestions(){const epoch=++questionEpoch,target=$('#questionRows');$('#questionSummary').textContent='იტვირთება…';try{const data=await rpc('admin_question_list',{p_search:questionSearch,p_status:questionStatus,p_topic:questionTopic,p_page:questionPage});if(epoch!==questionEpoch||!target.isConnected)return;$('#questionSummary').textContent=`${data.total} კითხვა · გვერდი ${data.total?questionPage+1:0}/${Math.ceil(data.total/10)}`;target.innerHTML=(data.items||[]).map(questionForm).join('')||'<p>კითხვა ვერ მოიძებნა.</p>';bindQuestionForms(data.items||[]);$('#questionPages').innerHTML=`<button id="questionPrev" ${questionPage===0?'disabled':''}>წინა</button><button id="questionNext" ${(questionPage+1)*10>=data.total?'disabled':''}>შემდეგი</button>`;$('#questionPrev').onclick=()=>{questionPage--;loadQuestions()};$('#questionNext').onclick=()=>{questionPage++;loadQuestions()}}catch(e){if(epoch===questionEpoch&&target.isConnected)$('#questionSummary').textContent=e.message}}
function bindQuestions(){$('#questionStatus').value=questionStatus;$('#questionTopic').value=questionTopic;$('#questionSearchForm').onsubmit=e=>{e.preventDefault();questionSearch=$('#questionSearch').value.trim();questionStatus=$('#questionStatus').value;questionTopic=$('#questionTopic').value;questionPage=0;loadQuestions()};$('#newQuestion').onclick=()=>{questionEpoch++;const q={status:'draft',difficulty:1,answer_index:0,topic:questionTopic};$('#questionRows').innerHTML=questionForm(q,0);$('#questionPages').innerHTML='';bindQuestionForms([q])};loadQuestions()}
function dailyPanel(){return `<section class="card"><h2>დღის ქუიზი</h2><p>15 კითხვა. დღევანდელი ნაკრები ყველასთვის ერთნაირია. თემა შემდეგ დღეებზეც გამოიყენება; შერეული არჩევანი აერთიანებს გამოქვეყნებულ კითხვებს.</p><label>თემა<select id="dailyTheme"><option value="">შერეული — ყველა თემა</option>${adminTopics.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label><div class="row"><button class="primary" id="prepareDaily">თემის შენახვა და მომზადება</button><button id="rebuildDaily">დღევანდელი ნაკრების შეცვლა</button></div><p id="dailyAdminStatus" aria-live="polite"></p></section>`}
async function loadDailyAdmin(){try{const s=await rpc('admin_daily_status');if(!$('#dailyAdminStatus'))return;$('#dailyTheme').value=s.theme||'';$('#dailyAdminStatus').textContent=`${s.day} · ${s.questions}/15 კითხვა მომზადებულია · ${s.attempts} დაწყებული თამაში · ${s.available} ხელმისაწვდომი კითხვა`;$('#rebuildDaily').disabled=s.attempts>0}catch(e){if($('#dailyAdminStatus'))$('#dailyAdminStatus').textContent=e.message}}
function bindDailyAdmin(){loadDailyAdmin();for(const [id,rebuild] of [['prepareDaily',false],['rebuildDaily',true]])$('#'+id).onclick=async()=>{const b=$('#'+id);b.disabled=true;try{await rpc('admin_prepare_daily',{p_theme:$('#dailyTheme').value||null,p_rebuild:rebuild});await loadDailyAdmin()}catch(e){$('#dailyAdminStatus').textContent=e.message}finally{if(b.isConnected){b.disabled=false;if(rebuild)try{const current=await rpc('admin_daily_status');if(b.isConnected)b.disabled=current.attempts>0}catch{}}}}}
function uploadPanel(){return `<section class="card"><h2>ფაილების ატვირთვა</h2><p>ჯერ კითხვები, შემდეგ კატალოგი. ძირითადი ბაზა და სრულად შევსებული ქუიზები ავტომატურად ქვეყნდება; სარეზერვო ბაზა ინახება მონახაზად.</p><label>კითხვების JSON — მაქსიმუმ 10,000 ჩანაწერი<input type="file" id="import" accept=".json,application/json"></label><label>ქუიზების კატალოგის JSON<input type="file" id="importQuiz" accept=".json,application/json"></label><p id="importProgress" aria-live="polite">${esc(importNotice)}</p><div id="familyDrafts"></div><button id="publishReady">მზად მყოფი ქუიზების გამოქვეყნება</button><p id="publishReadyMessage"></p></section>`}
async function admin(initialTab='quizzes'){setActiveView('admin');stopUpdates();questionEpoch++;editorEpoch++;if(!auth||!info.editor){main.innerHTML='<h1>საიტის მართვა</h1><p>ეს გვერდი მხოლოდ შესული ადმინისტრატორისთვისაა.</p>';return}main.innerHTML='<h1>საიტის მართვა</h1><p>იტვირთება…</p>';let stats;try{stats=await rpc('admin_dashboard')}catch(e){main.innerHTML='<h1>საიტის მართვა</h1><p class="error">'+esc(e.message)+'</p><p>Supabase-ში გაუშვით ახალი admin-full.sql ფაილი.</p>';return}adminTopics=stats.topics||[];main.innerHTML=`<h1>საიტის მართვა</h1><div class="stats"><span><strong>${stats.published}</strong>გამოქვეყნებული კითხვა</span><span><strong>${stats.drafts}</strong>მონახაზი</span><span><strong>${stats.live_quizzes}/${stats.quizzes}</strong>გამოქვეყნებული ქუიზი</span></div><div class="row admin-tabs" role="tablist">${[['quizzes','ქუიზები'],['questions','კითხვები'],['upload','ატვირთვა'],['daily','დღის ქუიზი'],['sources','წყაროები']].map(([v,t])=>`<button role="tab" data-admin-tab="${v}" aria-selected="${v==='quizzes'}" class="${v==='quizzes'?'primary':''}">${t}</button>`).join('')}</div><section id="adminContent"></section>`;const show=tab=>{stopUpdates();questionEpoch++;editorEpoch++;document.querySelectorAll('[data-admin-tab]').forEach(b=>{b.classList.toggle('primary',b.dataset.adminTab===tab);b.setAttribute('aria-selected',String(b.dataset.adminTab===tab))});const content=$('#adminContent');if(tab==='quizzes'){content.innerHTML=quizEditorPanel();bindQuizEditor()}else if(tab==='questions'){content.innerHTML=questionPanel();bindQuestions()}else if(tab==='daily'){content.innerHTML=dailyPanel();bindDailyAdmin()}else if(tab==='sources'){content.innerHTML=updatePanel();bindUpdates()}else{content.innerHTML=uploadPanel();$('#importQuiz').onchange=e=>bulkImport('quizzes',e.target.files[0]);$('#import').onchange=e=>bulkImport('questions',e.target.files[0]);loadFamilies();$('#publishReady').onclick=async()=>{try{const n=await rpc('publish_ready_quizzes');$('#publishReadyMessage').textContent=`გამოქვეყნდა ${n} ქუიზი.`;await refreshInfo()}catch(e){$('#publishReadyMessage').textContent=e.message}}}};document.querySelectorAll('[data-admin-tab]').forEach(b=>b.onclick=()=>show(b.dataset.adminTab));show(initialTab)}

$('#authForm').onsubmit=async e=>{e.preventDefault();await authAction(false)};$('#signup').onclick=()=>authAction(true);
async function authAction(signup){if(busy)return;if(!$('#authForm').reportValidity())return;if(signup&&$('#nickname').value.trim().length<2){$('#authMessage').textContent='შეიყვანეთ მინიმუმ 2-სიმბოლოიანი მეტსახელი';return}busy=true;try{const body={email:$('#email').value,password:$('#password').value,...(signup?{data:{nickname:$('#nickname').value.trim()}}:{})};const r=await api(signup?'/auth/v1/signup':'/auth/v1/token?grant_type=password',body,'POST',false);if(r.access_token){saveAuth(r);$('#auth').close();$('#password').value='';await refreshInfo();home()}else $('#authMessage').textContent='შეამოწმეთ ელფოსტა ანგარიშის დასადასტურებლად.'}catch(e){$('#authMessage').textContent=e.message}finally{busy=false}}
$('#account').onclick=async()=>{if(auth){try{await api('/auth/v1/logout',{})}catch{}saveAuth(null);await refreshInfo();home()}else if(connected())$('#auth').showModal();else $('#settings').showModal()};$('#closeAuth').onclick=()=>$('#auth').close();$('#closeSettings').onclick=()=>$('#settings').close();$('#setup').onclick=()=>{$('#url').value=config?.url||'';$('#key').value=config?.key||'';$('#settings').showModal()};$('#settingsForm').onsubmit=async e=>{e.preventDefault();const u=new URL($('#url').value);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')){alert('გამოიყენეთ https://…supabase.co მისამართი');return}const key=$('#key').value.trim();let role='';try{role=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).role}catch{}if(key.startsWith('sb_secret_')||role==='service_role'){alert('საიდუმლო გასაღები აკრძალულია');return}saveAuth(null);config={url:u.origin,key};localStorage.setItem('quizConfig',JSON.stringify(config));$('#settings').close();await refreshInfo();home()};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>({home,quizzes,leaders,admin}[b.dataset.view])());$('.brand').onclick=e=>{e.preventDefault();home()};if(localStorage.getItem('quizTheme')==='dark')document.body.classList.add('dark');$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('quizTheme',document.body.classList.contains('dark')?'dark':'light')};saveAuth(auth);refreshInfo().then(home);
